import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip } from 'recharts';
import { TranslationData } from '../types';

interface Props {
  content: TranslationData['foundation'];
}

const COLORS = ['#059669', '#84cc16', '#0ea5e9'];

const FoundationSection: React.FC<Props> = ({ content }) => {
  const data = [
    { name: content.chartLabels[0], value: 150 },
    { name: content.chartLabels[1], value: 30 },
    { name: content.chartLabels[2], value: 20 },
  ];

  return (
    <div className="bg-white rounded-xl shadow-lg p-6 md:p-8 transition-transform hover:shadow-xl">
      <div className="mb-6 border-l-4 border-emerald-600 pl-4">
        <h3 className="text-2xl font-bold text-slate-800 uppercase tracking-wider">{content.title}</h3>
        <p className="text-slate-600 mt-2">{content.description}</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-center">
        {/* Stats Grid */}
        <div className="grid grid-cols-2 gap-4">
          {[
            { val: 250, label: content.stats.land },
            { val: 5, label: content.stats.pillars },
            { val: 3, label: content.stats.yearsToIpo },
            { val: "6+", label: content.stats.exp }
          ].map((stat, idx) => (
            <div key={idx} className="bg-emerald-50 p-4 rounded-lg text-center border border-emerald-100 flex flex-col justify-center items-center h-32">
              <div className="text-3xl font-black text-emerald-600">{stat.val}</div>
              <div className="text-xs uppercase font-bold text-slate-500 mt-1">{stat.label}</div>
            </div>
          ))}
        </div>

        {/* Chart */}
        <div className="flex flex-col items-center">
          <h4 className="text-center font-bold text-slate-700 mb-4">{content.chartTitle}</h4>
          <div className="w-full h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={data}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {data.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36} iconType="circle" />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FoundationSection;

import React from 'react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer } from 'recharts';
import { TranslationData } from '../types';

interface Props {
  content: TranslationData['ecosystem'];
}

const EcosystemSection: React.FC<Props> = ({ content }) => {
  const data = content.chartLabels.map((label, index) => ({
    subject: label,
    A: [85, 75, 60, 90, 70][index],
    fullMark: 100,
  }));

  return (
    <div className="bg-white rounded-xl shadow-lg p-6 md:p-8">
      <div className="mb-8 border-l-4 border-emerald-600 pl-4">
        <h3 className="text-2xl font-bold text-slate-800 uppercase tracking-wider">{content.title}</h3>
        <p className="text-slate-600 mt-2">{content.description}</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
        <div className="bg-slate-50 rounded-xl p-4 border border-slate-100 flex items-center justify-center h-80 lg:h-auto">
          <ResponsiveContainer width="100%" height="100%">
            <RadarChart cx="50%" cy="50%" outerRadius="80%" data={data}>
              <PolarGrid />
              <PolarAngleAxis dataKey="subject" tick={{ fontSize: 12, fill: '#475569' }} />
              <Radar
                name="Revenue Strength"
                dataKey="A"
                stroke="#059669"
                strokeWidth={2}
                fill="#10b981"
                fillOpacity={0.4}
              />
            </RadarChart>
          </ResponsiveContainer>
        </div>

        <div className="space-y-6">
          {content.pillars.map((pillar, idx) => (
            <div key={idx} className="flex items-start">
              <div className="bg-emerald-600 text-white rounded-full w-8 h-8 flex items-center justify-center font-bold mr-4 mt-1 flex-shrink-0 shadow-md">
                {idx + 1}
              </div>
              <div>
                <h4 className="font-bold text-slate-800 text-lg">{pillar.title}</h4>
                <p className="text-slate-600 leading-relaxed">{pillar.desc}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default EcosystemSection;

import React from 'react';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from 'recharts';
import { TranslationData } from '../types';

interface Props {
  content: TranslationData['market'];
}

const MarketSection: React.FC<Props> = ({ content }) => {
  const leafData = [
    { year: '2020', price: 30 },
    { year: '2022', price: 40 },
    { year: '2024', price: 58 },
    { year: '2026', price: 80 },
  ];

  const carbonData = content.carbonLabels.map((label, idx) => ({
    name: label,
    value: [30000, 50000, 80000][idx]
  }));

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white p-2 border border-slate-200 shadow-md rounded text-xs">
          <p className="font-bold">{label}</p>
          <p className="text-emerald-600">{payload[0].value}</p>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
      {/* Leaves Chart */}
      <div className="bg-white rounded-xl shadow-lg p-6">
        <h4 className="font-bold text-slate-800 mb-2 border-b-2 border-lime-400 inline-block">
          {content.leafTitle}
        </h4>
        <p className="text-xs text-slate-500 mb-6 min-h-[32px]">{content.leafDesc}</p>
        <div className="h-60">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={leafData}>
              <defs>
                <linearGradient id="colorPrice" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#84cc16" stopOpacity={0.8}/>
                  <stop offset="95%" stopColor="#84cc16" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="year" tick={{fontSize: 12}} />
              <YAxis tick={{fontSize: 12}} />
              <Tooltip content={<CustomTooltip />} />
              <Area type="monotone" dataKey="price" stroke="#65a30d" fillOpacity={1} fill="url(#colorPrice)" />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Carbon Chart */}
      <div className="bg-white rounded-xl shadow-lg p-6">
        <h4 className="font-bold text-slate-800 mb-2 border-b-2 border-teal-400 inline-block">
          {content.carbonTitle}
        </h4>
        <p className="text-xs text-slate-500 mb-6 min-h-[32px]">{content.carbonDesc}</p>
        <div className="h-60">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={carbonData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="name" tick={{fontSize: 10}} interval={0} />
              <YAxis tick={{fontSize: 12}} />
              <Tooltip content={<CustomTooltip />} cursor={{fill: 'transparent'}} />
              <Bar dataKey="value" fill="#0d9488" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default MarketSection;

import React from 'react';
